def _team_link_from_table24(
    club_duni: int, table24_raw: bytes, stadium_table_raw: bytes
) -> tuple[int, int, int, dict[str, Any]]:
    """Find the matching team row and its Tsti row-index reference.

    Empirically, team records reuse the club DUNI. The Tsti reference is at
    DUNI+26 for the inspected rows; a small +25 variant occurs in the Dalian
    records. The value is accepted only if it resolves to a verified table_21
    rdui/duni identity.
    """
    count = _validate_fixed_stadium_table(stadium_table_raw)
    duni_bytes = struct.pack("<Q", club_duni)
    positions = _find_all(table24_raw, duni_bytes, limit=100)
    if not positions:
        raise LookupError(f"club DUNI 0x{club_duni:016x} not found in server table_24")

    valid: list[tuple[int, int, int, dict[str, Any]]] = []
    for team_offset in positions:
        for relative_offset in (26, 25):
            if team_offset + relative_offset + 4 > len(table24_raw):
                continue
            stadium_rdui = _u32(table24_raw, team_offset + relative_offset)
            if stadium_rdui >= count:
                continue
            try:
                stadium = _stadium_from_base_row(stadium_table_raw, stadium_rdui)
            except ValueError:
                continue
            valid.append((team_offset, relative_offset, stadium_rdui, stadium))
    # The schema-position +26 interpretation has priority when valid; +25 is
    # retained for rows whose record preamble is one byte shorter.
    valid.sort(key=lambda item: (item[1] != 26, item[0]))
    if not valid:
        raise LookupError(
            f"no verified Team.Tsti row-index reference for club DUNI 0x{club_duni:016x}"
        )
    chosen = valid[0]
    return chosen[0], chosen[1], chosen[2], chosen[3]


def _candidate_club_dunis(
    table3_raw: bytes, table24_raw: bytes, name_offsets: list[int]
) -> list[dict[str, int]]:
    candidates: dict[int, dict[str, int]] = {}
    for name_offset in name_offsets:
        nearby = _duni_candidates_near_name(table3_raw, name_offset)
        # A repeated-u32 DUNI can also look repeated when scanned one byte into
        # its first u32. Prefer the observed -40 start; use -39 only when -40
        # is not itself a repeated-u32 value (the Dalian rows are that variant).
        preferred_delta = -40 if any(delta == -40 for _, delta in nearby) else -39
        for duni, delta in nearby:
            if delta != preferred_delta:
                continue
            packed = struct.pack("<Q", duni)
            if table24_raw.find(packed) < 0:
                continue
            candidates.setdefault(
                duni,
                {"duni": duni, "name_offset": name_offset, "identity_delta": delta},
            )
    return list(candidates.values())


